import json
from collections import Counter
path = "tests/fixtures/claude_code_session.jsonl"
types = Counter()
block_types = Counter()
tool_names = Counter()
for i, line in enumerate(open(path)):
    line=line.strip()
    if not line: continue
    try:
        rec = json.loads(line)
    except Exception as e:
        types["UNPARSEABLE"] += 1
        continue
    if not isinstance(rec, dict):
        types["NONDICT"] += 1
        continue
    t = rec.get("type")
    types[t]+=1
    msg = rec.get("message")
    if isinstance(msg, dict):
        c = msg.get("content")
        if isinstance(c, list):
            for b in c:
                if isinstance(b, dict):
                    bt = b.get("type")
                    block_types[(t,bt)]+=1
                    if bt=="tool_use":
                        tool_names[b.get("name")]+=1
                else:
                    block_types[(t,"NONDICT_BLOCK")]+=1
        elif isinstance(c, str):
            block_types[(t,"STR_CONTENT")]+=1
        else:
            block_types[(t,type(c).__name__)]+=1
    else:
        block_types[(t, "NO_MESSAGE" if msg is None else type(msg).__name__)]+=1
print("record types:", dict(types))
print("block types:", dict(block_types))
print("tools:", dict(tool_names))
EOF

