    msg = r.get("message")
    if r.get("type")=="user" and isinstance(msg, dict) and isinstance(msg.get("content"), list):
        for b in msg["content"]:
            if isinstance(b, dict) and b.get("type")=="tool_result":
                tid = b.get("tool_use_id")
